<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class FacilityController extends Controller{
private function ok(Request $r,$manage=false){$u=$r->user();abort_unless($u->isSuperAdmin()||$u->hasRole('admin')||$u->hasRole('facility_head')||$u->canDo($manage?'facility.manage':'facility.view'),403);}
public function index(Request $r){$this->ok($r);$today=date('Y-m-d');$stats=['open'=>DB::table('facility_work_orders')->whereNotIn('status',['completed','cancelled'])->count(),'urgent'=>DB::table('facility_work_orders')->whereNotIn('status',['completed','cancelled'])->where('priority','urgent')->count(),'overdue'=>DB::table('facility_work_orders')->whereNotIn('status',['completed','cancelled'])->where('due_at','<',now())->count(),'service'=>DB::table('facility_maintenance_plans')->where('active',1)->where('next_on','<=',date('Y-m-d',strtotime('+14 days')))->count(),'lowstock'=>DB::table('facility_stock_items')->whereColumn('quantity','<=','minimum_quantity')->count(),'requests'=>DB::table('service_requests as x')->join('request_categories as c','c.id','=','x.request_category_id')->where('c.code','maintenance')->whereNotIn('x.status',['resolved','closed','cancelled'])->count()];$orders=DB::table('facility_work_orders as w')->leftJoin('facility_rooms as r','r.id','=','w.facility_room_id')->leftJoin('users as u','u.id','=','w.assigned_to')->select('w.*','r.number as room_number','u.name as assignee_name')->orderByRaw("CASE priority WHEN 'urgent' THEN 0 WHEN 'high' THEN 1 ELSE 2 END")->orderBy('due_at')->limit(30)->get();return view('facility.index',compact('stats','orders'));}
public function objects(Request $r){$this->ok($r,true);$buildings=DB::table('facility_buildings')->orderBy('name')->get();$rooms=DB::table('facility_rooms as r')->join('facility_buildings as b','b.id','=','r.facility_building_id')->leftJoin('users as u','u.id','=','r.responsible_user_id')->select('r.*','b.name as building_name','u.name as responsible_name')->orderBy('b.name')->orderBy('r.number')->get();$users=DB::table('users')->orderBy('name')->get();return view('facility.objects',compact('buildings','rooms','users'));}
public function building(Request $r){$this->ok($r,true);$d=$r->validate(['name'=>'required|string|max:500','address'=>'nullable|string|max:1000','area'=>'nullable|numeric|min:0','floors'=>'nullable|integer|min:1','note'=>'nullable|string|max:5000']);DB::table('facility_buildings')->insert($d+['status'=>'active','created_at'=>now(),'updated_at'=>now()]);return back();}
public function room(Request $r){$this->ok($r,true);$d=$r->validate(['facility_building_id'=>'required|exists:facility_buildings,id','number'=>'required|string|max:100','name'=>'nullable|string|max:500','type'=>'required|in:room,classroom,laboratory,office,warehouse,utility,workshop','area'=>'nullable|numeric|min:0','responsible_user_id'=>'nullable|exists:users,id']);DB::table('facility_rooms')->insert($d+['status'=>'active','created_at'=>now(),'updated_at'=>now()]);return back();}
public function assets(Request $r){$this->ok($r);$rows=DB::table('facility_assets as a')->leftJoin('facility_rooms as r','r.id','=','a.facility_room_id')->leftJoin('facility_buildings as b','b.id','=','r.facility_building_id')->leftJoin('users as u','u.id','=','a.responsible_user_id')->select('a.*','r.number as room_number','b.name as building_name','u.name as responsible_name')->orderBy('a.name')->get();$rooms=DB::table('facility_rooms as r')->join('facility_buildings as b','b.id','=','r.facility_building_id')->select('r.*','b.name as building_name')->orderBy('b.name')->get();$users=DB::table('users')->orderBy('name')->get();return view('facility.assets',compact('rows','rooms','users'));}
public function assetStore(Request $r){$this->ok($r,true);$d=$r->validate(['facility_room_id'=>'nullable|exists:facility_rooms,id','inventory_number'=>'nullable|string|max:100|unique:facility_assets,inventory_number','name'=>'required|string|max:500','category'=>'nullable|string|max:255','serial_number'=>'nullable|string|max:255','commissioned_on'=>'nullable|date','purchase_cost'=>'nullable|numeric|min:0','condition'=>'required|in:good,satisfactory,repair,unusable','responsible_user_id'=>'nullable|exists:users,id','next_service_on'=>'nullable|date','note'=>'nullable|string|max:5000']);DB::table('facility_assets')->insert($d+['status'=>'in_use','created_at'=>now(),'updated_at'=>now()]);return back();}
}